public static enum StaticFileStorageTarget {
        AZURE, GOOGLE
    }

public static Boolean deleteObjectFromAzure(String path) {
        Boolean isFileDeleted = Boolean.FALSE
        if (path) {
            String containerReference = path.split("/")[0]
            String blobReference = path.replaceAll("${containerReference}/", "")
            final String storageConnectionString = Holders.getFlatConfig().get("azure.storageConnectionString")
            try {
                CloudStorageAccount storageAccount = CloudStorageAccount.parse(storageConnectionString)
                CloudBlobClient blobClient = storageAccount.createCloudBlobClient()
                CloudBlobContainer container = blobClient.getContainerReference(containerReference)
                CloudBlockBlob blob = container.getBlockBlobReference(blobReference)
                blob.deleteIfExists()
                isFileDeleted = Boolean.TRUE
            }
            catch (Exception e) {
                log.error("Exception while deleting file to Azure ==>> ${e.message}", e)
            }
        }
        isFileDeleted
    }

